import { reserve, release } from '../inventory/InventoryService.js';
import { charge } from '../payments/PaymentService.js';
import { saveOrder } from './OrderRepository.js';

export async function createOrder(order) {
  if (!order.items.length) throw new Error('empty order');
  const reservation = await reserve(order.items);
  try {
    const receipt = await charge(order.total);
    return await saveOrder({ ...order, reservation, receipt });
  } catch (error) {
    await release(reservation);
    throw error;
  }
}

