import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const fixtureRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const action = process.argv.slice(2);
fs.appendFileSync(path.join(fixtureRoot, 'codegraph-calls.jsonl'), JSON.stringify(action) + '\n');
if (action[0] === 'status') {
  process.stdout.write(JSON.stringify({status:'stale', current:false, indexedRevision:'fixture-before', workingRevision:'fixture-after'}) + '\n');
} else {
  process.stderr.write('This controlled fixture only supports status.\n');
  process.exitCode = 1;
}

