const fs = require('node:fs');
const path = require('node:path');
const payload = JSON.parse(fs.readFileSync(0, 'utf8'));
if (!Array.isArray(payload.questions) || payload.questions.length < 1 || payload.questions.length > 3) throw new Error('Expected one to three questions');
for (const question of payload.questions) {
  if (typeof question.title !== 'string') throw new Error('Each question needs a title');
  if (question.options && (!Array.isArray(question.options) || question.options.length > 4)) throw new Error('At most four options per question');
}
fs.writeFileSync(path.join(__dirname, 'structured-question.json'), JSON.stringify(payload, null, 2));
process.stdout.write(JSON.stringify({status:'waiting_for_reply'}));
